buggy.described_examples:
import pandas as pd
import numpy as np

# Ensure pyarrow is available; these probes depend on it.
try:
    import pyarrow as pa
except Exception as e:
    pa = None


def record(name, fn):
    try:
        probe(name, fn())
    except Exception as e:
        probe_exception(name, e)


if pa is None:
    # If pyarrow is missing, we can't carry out the scenarios.
    probe(
        "ArrowDtype._get_common_dtype combining date32 / date64 with null[pyarrow]",
        None,
    )
    probe(
        "ArrowDtype._get_common_dtype combining timestamp[us, tz=US/Pacific] with null[pyarrow]",
        None,
    )
    probe(
        "ArrowDtype._get_common_dtype combining time32 / time64 / decimal128(7, 3) / binary / list_(int64) with null[pyarrow]",
        None,
    )
    probe(
        "ArrowDtype._get_common_dtype combining large_string with null[pyarrow]",
        None,
    )
else:
    from pandas.core.dtypes.dtypes import ArrowDtype
    from pandas.core.dtypes.common import is_dtype_equal

    def _dtype(x):
        return ArrowDtype(pa_type=x)

    null_pa = ArrowDtype(pa_type=pa.null())

    record(
        "ArrowDtype._get_common_dtype combining date32 / date64 with null[pyarrow]",
        lambda: ArrowDtype._get_common_dtype(
            _dtype(pa.date32()),
            _dtype(pa.date64()),
            null_pa,
        ),
    )

    record(
        "ArrowDtype._get_common_dtype combining timestamp[us, tz=US/Pacific] with null[pyarrow]",
        lambda: ArrowDtype._get_common_dtype(
            _dtype(pa.timestamp('us', tz='US/Pacific')),
            null_pa,
        ),
    )

    record(
        "ArrowDtype._get_common_dtype combining time32 / time64 / decimal128(7, 3) / binary / list_(int64) with null[pyarrow]",
        lambda: ArrowDtype._get_common_dtype(
            _dtype(pa.time32('s')),
            _dtype(pa.time64('us')),
            _dtype(pa.decimal128(7, 3)),
            _dtype(pa.binary()),
            _dtype(pa.list_(pa.int64())),
            null_pa,
        ),
    )

    record(
        "ArrowDtype._get_common_dtype combining large_string with null[pyarrow]",
        lambda: ArrowDtype._get_common_dtype(
            _dtype(pa.large_string()),
            null_pa,
        ),
    )

